    default: "Linear",
    description: "Linear tag",
  },
  logLabel: {
    type: "text-content",
    default: "Log",
    description: "Log tag",
  },
  morphAt: {
    type: "number",
    default: 64,
    min: 20,
    max: 100,
    step: 1,
    description: "Rescale at (frame)",
    hiddenFromList: false,
  },
  accent: {
