    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Hanken Grotesk",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
    hiddenFromList: false,
  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
